"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["204"],{14622(e){e.exports=JSON.parse('{"id":"V4-219","slug":"payment-rails","term":"Payment Rails","also_known_as":[],"difficulty":"Advanced","definition":"Payment rails are the underlying systems, networks and rules that move money between payers and payees, such as card networks, bank transfer systems and real-time payment systems.","explanation":["Every payment, whether by card, bank transfer or mobile app, travels over one or more payment rails. Different rails vary in speed, cost, availability and the types of payments they support.","Main types of payment rails include card networks, such as Visa and Mastercard; automated clearing house systems for batch bank transfers, such as ACH in the United States and Bacs in the United Kingdom; high-value systems for large transfers between banks, such as Fedwire, CHAPS and TARGET2; real-time payment systems, such as the UK\u2019s Faster Payments, India\u2019s UPI, Brazil\u2019s Pix and the US FedNow; and cross-border networks, such as SWIFT, which carries payment messages between banks.","For example, when a person pays a friend instantly through a banking app in India, the payment travels over UPI, settling within seconds.","Fintech companies build products on top of existing payment rails rather than creating their own. Choosing the right rail affects how quickly money arrives and how much it costs. New rails, such as blockchain-based systems and stablecoins, are also being developed and tested, particularly for cross-border payments, where existing systems can be slow and expensive."],"note":"","total":1725,"prev":{"slug":"payment-processor","term":"Payment Processor"},"next":{"slug":"payroll-tax","term":"Payroll Tax"}}')}}]);